ValidationRule.errorConditionFormula:
AND($RecordType.Name = "ASU Admission Services",
		NOT(ISBLANK(TEXT(Processing_Status__c))),
		NOT(
				OR(	CC_Sub_Category__r.Name= "Major Change",
		 			CC_Sub_Category__r.Name= "Fee Waiver Inquiry"
		 			)
 			),
		NOT(
			OR(	ISPICKVAL (Status, "Closed: Resolved"),
				ISPICKVAL (Status, "Closed: Customer Self-Resolved"), 
				ISPICKVAL (Status, "Closed: Customer Unresponsive")
				)
			)
		)
